mapper.select:
SELECT CASE WHEN USR_EML_CERT_YN = 'Y' THEN 1 ELSE 0 END
FROM USERS
WHERE USR_SN = #{userSn}

SELECT , CASE WHEN decision_status.PRV_STS_REG_ID REGEXP '^[0-9]+$' THEN CAST(decision_status.PRV_STS_REG_ID AS UNSIGNED) ELSE NULL END AS PROC_USR_SN, decision_status.PRV_STS_REG_DT, decision_status.PRV_STS_RSN_CN, permission.PRV_CAT_PRM_SN, permission.PRV_CAT_PRM_STATUS_CD, permission_status.CMM_NM AS PERMISSION_STATUS_NM, permission.PRV_CAT_PRM_USE_YN, permission.PRV_CAT_PRM_UPDT_DT FROM PROVIDER_APPLY a JOIN USERS u ON u.USR_SN = a.USR_SN JOIN CATEGORY c ON c.CAT_SN = a.CAT_SN JOIN CMM_CODE status_code ON status_code.CMM_CD = a.PRV_APLY_STATUS_CD LEFT JOIN PROVIDER_STATUS decision_status ON decision_status.PRV_STS_SN = ( SELECT history.PRV_STS_SN FROM PROVIDER_STATUS history WHERE history.PRV_APLY_SN = a.PRV_APLY_SN AND history.PRV_STS_CD IN ('PRVC0017', 'PRVC0018') ORDER BY history.PRV_STS_REG_DT DESC, history.PRV_STS_SN DESC LIMIT 1 ) LEFT JOIN PROVIDER_CATEGORY_PERMISSION permission ON permission.PRV_CAT_PRM_SN = ( SELECT permission_history.PRV_CAT_PRM_SN FROM PROVIDER_CATEGORY_PERMISSION permission_history WHERE permission_history.PRV_APLY_SN = a.PRV_APLY_SN ORDER BY permission_history.PRV_CAT_PRM_SN DESC LIMIT 1 ) LEFT JOIN CMM_CODE permission_status ON permission_status.CMM_CD = permission.PRV_CAT_PRM_STATUS_CD WHERE a.PRV_APLY_ACTV_YN = 'Y' AND a.PRV_APLY_STATUS_CD IN ('PRVC0002', 'PRVC0003', 'PRVC0004')
AND a.PRV_APLY_STATUS_CD = #{statusCode}
ORDER BY CASE a.PRV_APLY_STATUS_CD WHEN 'PRVC0002' THEN 0 WHEN 'PRVC0003' THEN 1 WHEN 'PRVC0004' THEN 2 ELSE 3 END ASC, a.PRV_APLY_REG_DT DESC, a.PRV_APLY_SN DESC

SELECT COUNT(*)
FROM PROVIDER_APPLY
WHERE USR_SN = #{userSn}
  AND CAT_SN = #{categorySn}
  AND PRV_APLY_ACTV_YN = 'Y'
  AND PRV_APLY_STATUS_CD = 'PRVC0002'

mapper.update:
UPDATE PROVIDER_CATEGORY_PERMISSION
   SET PRV_CAT_PRM_STATUS_CD = #{targetStatusCode},
       PRV_CAT_PRM_USE_YN = #{targetUseYn},
       PRV_CAT_PRM_UPDT_ID = #{actorId}
 WHERE PRV_CAT_PRM_SN = #{permissionSn}
   AND PRV_CAT_PRM_STATUS_CD = #{expectedStatusCode}
   AND PRV_CAT_PRM_USE_YN = #{expectedUseYn}

mapper.select:
SELECT EXISTS (
  SELECT 1
  FROM PROVIDER_CATEGORY_PERMISSION
  WHERE USR_SN = #{userSn}
    AND CAT_SN = #{categorySn}
    AND PRV_CAT_PRM_STATUS_CD = 'PRVC0006'
    AND PRV_CAT_PRM_USE_YN = 'Y'
)
